begin;create extension if not exists pgtap with schema extensions;select plan(15);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','e0000000-0000-0000-0000-000000000001','authenticated','authenticated','resend@example.test','',now(),'{}','{}',now(),now()),('00000000-0000-0000-0000-000000000000','e0000000-0000-0000-0000-000000000002','authenticated','authenticated','other@example.test','',now(),'{}','{}',now(),now());
insert into public.organizations(id,public_id,name)values('e1000000-0000-0000-0000-000000000001','org_resendaaaaaaaaaa','Resend A'),('e1000000-0000-0000-0000-000000000002','org_resendbbbbbbbbbb','Resend B');
insert into public.organization_memberships(id,organization_id,user_id,role,status)values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001','owner','active'),('e2000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','e0000000-0000-0000-0000-000000000002','owner','active');
insert into public.contacts(id,organization_id,created_by_membership_id,assigned_membership_id,first_name,last_name,primary_email,source,lifecycle_status,marketing_email_status)values('e3000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Ada','Resend','ada@example.test','Pack6A','nurture','opted-in'),('e3000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','Other','Tenant','other@example.test','Pack6A','nurture','opted-in');
set local role authenticated;select set_config('request.jwt.claim.sub','e0000000-0000-0000-0000-000000000001',true);
insert into public.contact_segments(organization_id,created_by_membership_id,name,criteria)values('e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Pack 6A','{"version":1,"combinator":"and","rules":[{"field":"source","operator":"is","value":"Pack6A"}]}');
insert into public.marketing_campaigns(organization_id,created_by_membership_id,name,subject,sender_name,reply_to,audience_type,audience_public_id,status,content)values('e1000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Resend events','Hello','Alex','alex@example.test','segment',(select public_id from public.contact_segments where name='Pack 6A'),'ready','{"version":1,"heading":"Hi","body":"Body","ctaLabel":"","ctaUrl":"","footer":"Footer"}');
select public.confirm_campaign_send((select public_id from public.marketing_campaigns where name='Resend events'),'pack6a-idempotency',false);select * from public.claim_campaign_recipients((select public_id from public.marketing_send_runs),10,'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee');select public.complete_campaign_recipient((select public_id from public.marketing_send_recipients),'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeeee','accepted','resend-message-1',null);
reset role;
select ok(has_function_privilege('service_role','public.record_marketing_provider_event(text,text,text,public.marketing_delivery_event_type,timestamptz,jsonb)','execute'),'service role can ingest verified provider events');
select ok(not has_function_privilege('authenticated','public.record_marketing_provider_event(text,text,text,public.marketing_delivery_event_type,timestamptz,jsonb)','execute'),'authenticated users cannot call provider ingestion');
select ok(public.record_marketing_provider_event('resend-message-1','resend','evt-delivered','delivered',now(),'{}'),'delivered event recorded');
select is((select status::text from public.marketing_send_recipients),'delivered','delivery reconciles recipient');
select ok(not public.record_marketing_provider_event('resend-message-1','resend','evt-delivered','delivered',now(),'{}'),'duplicate provider event is a no-op');
select is((select count(*) from public.marketing_delivery_events where provider_event_id='evt-delivered'),1::bigint,'duplicate creates one durable event');
select ok(public.record_marketing_provider_event('resend-message-1','resend','evt-hard','hard-bounce',now(),'{"bounceType":"Permanent"}'),'hard bounce event recorded');
select is((select status::text from public.marketing_send_recipients),'bounced','hard bounce reconciles recipient');
select is((select marketing_email_status::text from public.contacts where id='e3000000-0000-0000-0000-000000000001'),'suppressed','hard bounce suppresses future marketing');
update public.contacts set marketing_email_status='opted-in' where id='e3000000-0000-0000-0000-000000000001';
select ok(public.record_marketing_provider_event('resend-message-1','resend','evt-soft','soft-bounce',now(),'{}'),'soft bounce event recorded');
select is((select marketing_email_status::text from public.contacts where id='e3000000-0000-0000-0000-000000000001'),'opted-in','soft bounce does not revoke consent');
select ok(public.record_marketing_provider_event('resend-message-1','resend','evt-complaint','complaint',now(),'{}'),'complaint event recorded');
select is((select marketing_email_status::text from public.contacts where id='e3000000-0000-0000-0000-000000000001'),'suppressed','complaint suppresses future marketing');
select ok(not public.record_marketing_provider_event('unknown-message','resend','evt-unknown','delivered',now(),'{}'),'unknown provider message fails safely');
select is((select marketing_email_status::text from public.contacts where id='e3000000-0000-0000-0000-000000000002'),'opted-in','another organization remains unchanged');
select * from finish();rollback;
